elements=sorted(set(e.symbol for s in ss for e in s.composition.elements))
props=['Z','X','row','group','atomic_radius','atomic_mass','mendeleev_no','electron_affinity','ionization_energy','molar_volume']
ep={}
for e in elements:
 el=Element(e);ep[e]=[]
 for p in props:
  try: val=float(getattr(el,p)); val=val if np.isfinite(val) else 0
  except: val=0
  ep[e].append(val)
# atom channels, plus chemical categories
channels=['all','anion','cation','alkali','alkaline','group13','group14','group15','coin','d10','Z','X','radius']
def ch(e):
 el=Element(e);g=el.group
 return np.array([1,float(g in [16,17]),float(g not in [16,17]),float(g==1),float(g==2),float(g==13),float(g==14),float(g==15),float(g==11),float(g==12),el.Z/40,(el.X or 0)/2,float(el.atomic_radius or 1.5)])
chmat={e:ch(e) for e in elements}
recs=[]
def stats(f,name,vals,weights=None):
 vals=np.asarray(vals)
 if len(vals)==0: vals=np.zeros(1)
 f[name+'_mean']=np.average(vals,weights=weights);f[name+'_std']=np.sqrt(np.average((vals-f[name+'_mean'])**2,weights=weights));f[name+'_min']=np.min(vals);f[name+'_max']=np.max(vals)
def tens_stats(f,name,T):
 ev=np.linalg.eigvalsh(T)
 f[name+'_trace']=np.trace(T)
 f[name+'_aniso']=ev[-1]-ev[0];f[name+'_mid']=ev[1]-ev[0]
 f[name+'_norm']=np.linalg.norm(ev-ev.mean())
 # do not use tensor orientation yet, save secondary
 f[name+'_xx']=T[0,0]-np.trace(T)/3;f[name+'_yy']=T[1,1]-np.trace(T)/3;f[name+'_zz']=T[2,2]-np.trace(T)/3
 f[name+'_xy']=T[0,1];f[name+'_xz']=T[0,2];f[name+'_yz']=T[1,2]
for ix,s in enumerate(ss):
 f={}
 comp=s.composition.fractional_composition
 for el in elements: f['comp_'+el]=comp[el]
 arr=np.array([ep[site.specie.symbol] for site in s])
 for j,p in enumerate(props): stats(f,'elem_'+p,arr[:,j]);f['elem_'+p+'_range']=np.ptp(arr[:,j])
 f['nelem']=len(comp);f['volpa']=s.volume/len(s);f['density']=float(s.density);f['n']=len(s)
 an=SpacegroupAnalyzer(s,symprec=.05)
 f['sg']=an.get_space_group_number()
 for sys in ['triclinic','monoclinic','orthorhombic','tetragonal','trigonal','hexagonal','cubic']:
  f['system_'+sys]=int(an.get_crystal_system()==sys)
 for k,v in zip(['a','b','c','alpha','beta','gamma'],s.lattice.parameters): f['lattice_'+k]=v
 for k,v in zip(['a','b','c'],sorted(s.lattice.abc)):f['latsorted_'+k]=v
 abc=sorted(s.lattice.abc)
 f['latratio1']=abc[1]/abc[0];f['latratio2']=abc[2]/abc[0]
 ii,jj,images,dd=s.get_neighbor_list(8.5)
 vv=(s.frac_coords[jj]+images-s.frac_coords[ii])@s.lattice.matrix
 u=vv/dd[:,None];uu=u[:,:,None]*u[:,None,:]
 syms=np.array([site.specie.symbol for site in s]);ci=np.array([chmat[x] for x in syms[ii]]);cj=np.array([chmat[x] for x in syms[jj]])
 rr=np.array([float(site.specie.atomic_radius or 1.5) for site in s]);rnorm=dd/(rr[ii]+rr[jj])
 # isotropic radial distribution and weighted orientational order
 for mode in ['r','scaled']:
  x=dd if mode=='r' else rnorm
  centers=np.arange(1.5,7.51,.5) if mode=='r' else np.arange(.8,2.81,.2)
  width=.35 if mode=='r' else .15
  for cent in centers:
   w=np.exp(-.5*((x-cent)/width)**2)
   for c in range(len(channels)):
    cw=w*(ci[:,c]+cj[:,c])/2
    T=np.einsum('n,nij->ij',cw,uu)/s.volume
    tens_stats(f,f'rad_{mode}_{cent:.1f}_{channels[c]}',T)
 # power tensors with neighbor species and chemical bond contrasts
 for mode in ['r','scaled']:
  x=dd if mode=='r' else rnorm
  for p in [2,4,6,8]:
   w=(x/(2.5 if mode=='r' else 1.))**(-p)
   for c in range(len(channels)):
    T=np.einsum('n,nij->ij',w*(ci[:,c]+cj[:,c])/2,uu)/s.volume
    tens_stats(f,f'pow_{mode}_{p}_{channels[c]}',T)
 # detailed per-element local coordination and first shell geometry
 for g in ['all','anion','cation','alkali','alkaline','group13','group14','group15','coin','d10']:
  cidx=channels.index(g)
  site_ids=[i for i in range(len(s)) if chmat[syms[i]][cidx]>0]
  local={}
  for i in site_ids:
   mask=ii==i
   d=dd[mask];unit=u[mask];order=np.argsort(d);d=d[order];unit=unit[order]
   for nn in [3,4,6,8,12]:
    ds=d[:nn];us=unit[:nn]
    name=f'first{nn}'
    vals={'mean_r':np.mean(ds),'std_r':np.std(ds),'rmin':ds[0],'rmax':ds[-1],'gap':d[nn]-d[nn-1]}
    T=np.einsum('ni,nj->ij',us,us)/nn;ev=np.linalg.eigvalsh(T)
    vals['aniso']=np.ptp(ev);vals['mid']=ev[1]-ev[0];vals['vec']=np.linalg.norm(us.mean(axis=0))
    dots=(us@us.T)[np.triu_indices(nn,1)]
    vals['angmean']=np.mean(dots);vals['angstd']=np.std(dots);vals['angmin']=np.min(dots);vals['angmax']=np.max(dots)
    for key,val in vals.items(): local.setdefault(name+'_'+key,[]).append(val)
  for key,vals in local.items(): stats(f,'local_'+g+'_'+key,vals)
  if not site_ids:
   for nn in [3,4,6,8,12]:
    for key in ['mean_r','std_r','rmin','rmax','gap','aniso','mid','vec','angmean','angstd','angmin','angmax']:stats(f,'local_'+g+'_first'+str(nn)+'_'+key,[0])
 # pair specific tensors, and global first neighbor combined orientation
 for cutoff in [1.1,1.3,1.5,1.8]:
  dmin=np.array([dd[ii==i].min() for i in range(len(s))])
  w=(dd<dmin[ii]*cutoff).astype(float)
  for c in range(10):
   T=np.einsum('n,nij->ij',w*ci[:,c],uu)/s.volume
   tens_stats(f,f'shell_{cutoff}_{channels[c]}',T)
 recs.append(f)
 if ix%50==0:print(ix,flush=True)
X=pd.DataFrame(recs).fillna(0)
pickle.dump((X,df,meta),open('/tmp/features.pkl','wb'))
print(X.shape)

