 T=np.einsum('nijk,i->njk',F,c);ev=np.linalg.eigvalsh(T);return ev[:,-1]-ev[:,0]
def fit(F,y,reg,nstart=8):
 def residual(c):return np.r_[preds(c,F)-y,np.sqrt(reg)*c]
 rng=np.random.default_rng(23);best=None;fits=[]
 for j in range(nstart):
  init=np.ones(F.shape[1])*.01 if j==0 else rng.normal(size=F.shape[1])*.03
  res=least_squares(residual,init,max_nfev=150,ftol=1e-7,gtol=1e-7)
  fits.append(res)
  if best is None or np.sum(res.fun**2)<np.sum(best.fun**2):best=res
 return best.x,sorted(fits,key=lambda r:np.sum(r.fun**2))
results=[];outs={};oofs={}
for name,F in [('ew',ew),('rad',rad),('general',feat)]:
 scale=np.sqrt((F[:nt]**2).sum(axis=(0,2,3))/nt);F=F[:,scale>1e-8]/scale[None,scale>1e-8,None,None]
 for reg in [.01,.1,1.]:
  c,fits=fit(F[:nt],y,reg);oof=np.zeros(nt);cv=[]
  for tr,va in folds:
   cc,_=fit(F[tr],y[tr],reg,nstart=6);oof[va]=preds(cc,F[va]);cv.append(preds(cc,F[nt:]))
  score=np.mean(abs(oof-y));key=name+'_'+str(reg)
  print(key,'TRAIN',np.mean(abs(preds(c,F[:nt])-y)),'GROUP',score,flush=True)
  fp=np.array([preds(f.x,F[nt:]) for f in fits])
  print(pd.DataFrame({'id':meta.id.iloc[ipool].values,'full':preds(c,F[nt:]),'cvmedian':np.median(cv,axis=0),'stdinit':fp.std(axis=0),'cvsd':np.std(cv,axis=0)}).round(4).to_string(index=False),flush=True)
  results.append((key,score));outs[key]=(preds(c,F[nt:]),np.array(cv),fp);oofs[key]=oof
  pickle.dump((itra,ipool,results,outs,oofs),open('/tmp/robustpreds.pkl','wb'))

