inds,itra,ipool,ew,rad,feat=pickle.load(open('/tmp/tensorfeatures.pkl','rb'));X,df,meta=pickle.load(open('/tmp/features.pkl','rb'));_,ss,_=pickle.load(open('/tmp/structures.pkl','rb'));nt=len(itra);y=df.dn.iloc[itra].values;groups=np.array([ss[i].composition.reduced_formula for i in itra]);folds=list(LeaveOneGroupOut().split(itra,groups=groups));kfolds=list(KFold(5,shuffle=True,random_state=5).split(itra));results=[];outs={};oofs={}
for name,F in [('ew',ew),('rad',rad),('general',feat)]:
 scale=np.sqrt((F[:nt]**2).sum(axis=(0,2,3))/nt);F=F[:,scale>1e-8]/scale[None,scale>1e-8,None,None]
 nf=F.shape[1];G=np.einsum('npab,nqab->npq',F,F)
 # cross tensor inner products, no arbitrary crystal axes
 upper=np.triu_indices(nf);xp=G[:,upper[0],upper[1]];xp[:,upper[0]!=upper[1]]*=np.sqrt(2.)
 ev=np.linalg.eigvalsh(F);xa=np.concatenate([ev[:,:,-1]-ev[:,:,0],ev[:,:,1]-ev[:,:,0]],axis=1)
 print(name,nf,flush=True)
 for modeltype in ['quad','plain','krr','et']:
  for reg in ([.1,1.,10.,100.] if modeltype in ['quad','plain'] else [.1,1.] if modeltype=='krr' else [1]):
   XX=xp if modeltype=='quad' else xa
   def make():
    if modeltype in ['quad','plain']:return Ridge(alpha=reg,fit_intercept=modeltype!='quad')
    if modeltype=='krr':return make_pipeline(StandardScaler(),KernelRidge(alpha=.05,kernel='rbf',gamma=reg/xa.shape[1]))
    return ExtraTreesRegressor(n_estimators=250,max_features=1.,random_state=42,n_jobs=2)
   def trainpred(tr,va):
    m=make()
