    else:m.fit(XX[tr],np.arcsinh(y[tr]/.1));p=.1*np.sinh(m.predict(XX[va]))
    return p
   of=np.zeros(nt);ofk=of.copy();pp=[]
   for tr,va in folds:of[va]=trainpred(tr,va);pp.append(trainpred(tr,np.arange(nt,len(inds))))
   for tr,va in kfolds:ofk[va]=trainpred(tr,va)
   full=trainpred(np.arange(nt),np.arange(nt,len(inds)));key=name+'_'+modeltype+'_'+str(reg);s=np.mean(abs(of-y));sk=np.mean(abs(ofk-y));print(key,s,sk,flush=True)
   results.append((key,s,sk));outs[key]=(full,np.array(pp));oofs[key]=(of,ofk)
   pickle.dump((itra,ipool,results,outs,oofs),open('/tmp/quadpreds.pkl','wb'))

